# Oct 16: painted, blurred impressions of a magazine cover layout: a cover subject filling the frame, the publication's
# color scheme, a masthead band and coverline bars. Original shapes only: no logos, no real photos, no lettering.
import random, sys
from PIL import Image, ImageDraw, ImageFilter
W,H=640,820
OUT=sys.argv[1] if len(sys.argv)>1 else 'assets/press/'
def grad(c1,c2):
    im=Image.new('RGB',(W,H),c1); d=ImageDraw.Draw(im)
    for y in range(H):
        t=y/H; d.line([(0,y),(W,y)],fill=tuple(int(c1[i]+(c2[i]-c1[i])*t) for i in range(3)))
    return im
def person(d,cx,top,scale,skin,hair,cloth,shadow=(0,0,0,70)):
    s=scale
    d.ellipse([cx-150*s,top+260*s,cx+150*s,top+620*s],fill=cloth)            # shoulders
    d.rectangle([cx-40*s,top+200*s,cx+40*s,top+300*s],fill=skin)             # neck
    d.ellipse([cx-85*s,top+40*s,cx+85*s,top+250*s],fill=skin)                # face
    d.ellipse([cx-95*s,top+10*s,cx+95*s,top+130*s],fill=hair)                # hair top
    d.ellipse([cx-60*s,top+150*s,cx+60*s,top+250*s],fill=shadow)             # jaw shade
def cover(name,bg1,bg2,mast,subject,lines,blur=7,band=None):
    random.seed(name)
    im=grad(bg1,bg2); d=ImageDraw.Draw(im,'RGBA')
    for (kind,*a) in subject:
        if kind=='p': person(d,*a)
        elif kind=='o': cx,cy,r,col=a; d.ellipse([cx-r,cy-r,cx+r,cy+r],fill=col)
        elif kind=='r': x,y,w,h,col=a; d.rectangle([x,y,x+w,y+h],fill=col)
    if band: d.rectangle([0,0,W,band[1]],fill=band[0])
    if mast: d.rectangle([40,38,W-40,38+mast[1]],fill=mast[0])
    for (x,y,w,h,col) in lines: d.rounded_rectangle([x*W,y*H,(x+w)*W,(y+h)*H],radius=4,fill=col)
    im=im.filter(ImageFilter.GaussianBlur(blur))
    im.save(OUT+name+'.webp',quality=78)
